    // because the zero can be in any of the (k-1) positions (not the MSB)

    // We need to count numbers in [a, b] that have exactly one zero in binary

    function countUpTo(n) {
        // Count numbers from 1 to n that have exactly one zero in binary
        if (n <= 0n) return 0n;

