        let num = n;
        const bits = [];

        // Get binary representation
        while (num > 0n) {
            bits.push(num % 2n);
            num = num >> 1n;
        }

        const k = bits.length; // number of bits

        // For each bit length from 2 to k-1, all numbers with that many bits
        // that have exactly one zero are valid
        for (let len = 2; len < k; len++) {
